import { FunctionalComponent,JSX } from 'preact';
import { useState } from 'preact/hooks';
import { getTranslation } from '../../../../../shared/chromeApi';

import styles from './styles.module.scss';
import { Tile } from '../../slice/types';

interface LinkDialogProps {
  initData: Tile;
  onClose: () => void;
  onSubmit: (data) => void;
  onRemove: () => void;
}

const LinkDialog: FunctionalComponent<LinkDialogProps> = ({
  initData,
  onClose,
  onSubmit,
  onRemove,
}: LinkDialogProps) => {
  const [data, setData] = useState(initData || { title: '', url: '' });
  const isAdTile = initData.type === 'adTiles';

  const handleChange = (
    e: JSX.TargetedEvent<HTMLInputElement, Event>
  ): void => {
    const target = e.target as HTMLInputElement;
    setData({ ...data, [target.name]: target.value });
  };

  const isValidURL = (): boolean =>
    /(http(s)?:\/\/.)?(www\.)?[-a-zA-Z0-9@:%._+~#=]{2,256}\.[a-z]{2,6}\b([-a-zA-Z0-9@:%_+.~#?&//=]*)/g.test(
      data.url
    );

  return (
    <div className={styles.dialog}>
      <div className={styles.dialogContent}>
        <h2 className={styles.title}>
          {getTranslation(
            `new_tab_dialog_title_${
              initData.url ? `edit${isAdTile ? '_ad' : ''}` : 'add'
            }`
          )}
        </h2>
        <div>
          <div>
            <label>{getTranslation('new_tab_dialog_label_title')}</label>
            <input
              value={data.title}
              name="title"
              disabled={isAdTile}
              onChange={handleChange}
            />
          </div>
          <div>
            <label>{getTranslation('new_tab_dialog_label_url')}</label>
            <input
              value={data.url}
              name="url"
              disabled={isAdTile}
              onChange={handleChange}
            />
          </div>
          <div className={styles.buttonsGroup}>
            {initData.url && (
              <button
                className={`${styles.btn} ${styles.btnSecondary}`}
                type="button"
                onClick={onRemove}
              >
                {getTranslation('new_tab_dialog_button_remove')}
              </button>
            )}

            <button
              onClick={onClose}
              className={`${styles.btn} ${styles.btnSecondary}`}
              type="button"
              style="margin-left: auto"
            >
              {getTranslation('new_tab_dialog_button_cancel')}
            </button>

            <button
              onClick={(): void => onSubmit(data)}
              className={`${styles.btn} ${styles.btnPrimary}`}
              style="margin-left: 10px"
              disabled={!isValidURL()}
            >
              {getTranslation('new_tab_dialog_button_done')}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default LinkDialog;
